// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.List;

import org.junit.jupiter.api.Test;

/**
 * Pins the frontier rule of the adaptive arbitration's domination phase, as documented on
 * {@link LmdbNativeStrategyPreference} and implemented by the legacy arbiter: candidates strictly dominated by some
 * rival are removed first, and static preference decides among the non-dominated survivors. A candidate may only lose
 * by being dominated itself — never because a rival happened to dominate whichever candidate was selected so far.
 */
class LmdbNativeAdaptiveArbitrationTest {

	/**
	 * Preference order [expensive, mid, cheap] with 95% intervals [100,200], [50,150] and [10,60]: cheap strictly
	 * dominates expensive alone (60 &lt; 100) while mid overlaps both. The frontier is {mid, cheap}, so mid — the
	 * highest-preference undominated candidate — must win. A greedy scan that only compares rivals against the current
	 * selection lets cheap capture the choice by beating expensive, even though mid was never dominated.
	 */
	@Test
	void undominatedHigherPreferenceCandidateMustNotLoseToARivalThatOnlyBeatsTheIncumbent() {
		// Under the latent displacement test: cheap (mean 45) clears the 99% margin against expensive (mean 150)
		// but not against mid (mean 80, whose uncertainty overlaps), so the frontier is {mid, cheap} and mid — the
		// higher-preference undominated candidate — must win. A greedy scan that only compares rivals against the
		// current selection would let cheap capture the choice by beating expensive alone.
		LmdbNativeAdaptiveArbitration.Priced<String> expensive = priced("expensive", 0, 100, 150, 200);
		LmdbNativeAdaptiveArbitration.Priced<String> mid = priced("mid", 1, 40, 80, 120);
		LmdbNativeAdaptiveArbitration.Priced<String> cheap = priced("cheap", 2, 15, 45, 90);

		LmdbNativeAdaptiveArbitration.Priced<String> selected = LmdbNativeAdaptiveArbitration
				.selectWithinFrontier(List.of(expensive, mid, cheap));

		assertSame(mid, selected,
				"mid is never strictly dominated and outranks cheap in static preference; it may not "
						+ "lose to a rival that only dominated the incumbent");
	}

	/**
	 * The legacy arbiter's documented tie case: two equally cheap candidates both dominate an expensive specialist of
	 * higher preference; neither cheap candidate dominates the other, and their tie must not resurrect the dominated
	 * specialist merely because it has a higher preference rank.
	 */
	@Test
	void dominatedSpecialistIsNotResurrectedByATieAmongItsDominators() {
		LmdbNativeAdaptiveArbitration.Priced<String> specialist = priced("specialist", 0, 500, 600, 700);
		LmdbNativeAdaptiveArbitration.Priced<String> firstCheap = priced("firstCheap", 1, 10, 30, 60);
		LmdbNativeAdaptiveArbitration.Priced<String> secondCheap = priced("secondCheap", 2, 20, 40, 70);

		LmdbNativeAdaptiveArbitration.Priced<String> selected = LmdbNativeAdaptiveArbitration
				.selectWithinFrontier(List.of(specialist, firstCheap, secondCheap));

		assertSame(firstCheap, selected,
				"the specialist is dominated by both cheap candidates and must not win their tie");
	}

	/**
	 * Gap-analysis C9: the documented stricter bar for order-losing rewrites. A same-family candidate that loses the
	 * incumbent's property preservation may displace it only when it dominates even at the 99% interval — the 95%
	 * interval alone (the general rule) is not enough. Here the candidate 95-dominates (90 &lt; 100) but its 99% high
	 * (97) overlaps the incumbent's 99% low (95), so the incumbent must be retained.
	 */
	@Test
	void orderLosingRewriteNeedsNinetyNineDomination() {
		LmdbNativeAdaptiveArbitration.Priced<String> preserving = pricedWithProperties("family-x", 0, 100, 150, 200,
				95, 205, true);
		LmdbNativeAdaptiveArbitration.Priced<String> hashing = pricedWithProperties("family-x", 1, 10, 50, 90,
				8, 97, false);

		LmdbNativeAdaptiveArbitration.Priced<String> selected = LmdbNativeAdaptiveArbitration
				.selectWithinFrontier(List.of(preserving, hashing));

		assertSame(preserving, selected,
				"an order-losing same-family rewrite that only 95-dominates must not displace the "
						+ "property-preserving incumbent");
	}

	/** The stricter bar still admits a rewrite that truly dominates at the 99% interval. */
	@Test
	void orderLosingRewriteWithNinetyNineDominationStillWins() {
		LmdbNativeAdaptiveArbitration.Priced<String> preserving = pricedWithProperties("family-x", 0, 100, 150, 200,
				95, 205, true);
		LmdbNativeAdaptiveArbitration.Priced<String> hashing = pricedWithProperties("family-x", 1, 10, 40, 70,
				8, 80, false);

		LmdbNativeAdaptiveArbitration.Priced<String> selected = LmdbNativeAdaptiveArbitration
				.selectWithinFrontier(List.of(preserving, hashing));

		assertSame(hashing, selected, "99% domination (80 < 95) satisfies the stricter bar");
	}

	/**
	 * HIGHLY_CONNECTED q4, 2026-08-16: `irKernelInterpreted` won arbitration with
	 * {@code expectedNanos=0.0; evidence=0; source=STRUCTURAL_ONLY} against a nestedLoop incumbent carrying 199 samples
	 * of real timing history, purely by ladder rank. A candidate that has never run may not displace measured rivals
	 * silently: the cold-start guard hands the choice to the measured rival with the lowest expected cost.
	 */
	@Test
	void unmeasuredIncumbentLosesToTheCheapestMeasuredRival() {
		LmdbNativeAdaptiveArbitration.Priced<String> unmeasured = structuralOnly("newKernel", 0);
		LmdbNativeAdaptiveArbitration.Priced<String> slowMeasured = pricedWithEvidence("slowLoop", 1,
				5_000_000, 10_000_000, 20_000_000, 199);
		LmdbNativeAdaptiveArbitration.Priced<String> fastMeasured = pricedWithEvidence("fastLoop", 2,
				50_000, 100_000, 200_000, 199);

		LmdbNativeAdaptiveArbitration.Priced<String> rescued = LmdbNativeAdaptiveArbitration
				.coldStartRescue(List.of(unmeasured, slowMeasured, fastMeasured));

		assertSame(fastMeasured, rescued,
				"an incumbent with zero exact evidence must yield to the cheapest measured rival");
	}

	/** The guard exists solely for unmeasured incumbents; once the incumbent has run, cost rules apply as usual. */
	@Test
	void measuredIncumbentIsNeverRescuedAway() {
		LmdbNativeAdaptiveArbitration.Priced<String> measuredIncumbent = pricedWithEvidence("kernel", 0,
				5_000_000, 10_000_000, 20_000_000, 9);
		LmdbNativeAdaptiveArbitration.Priced<String> fastRival = pricedWithEvidence("loop", 1,
				50_000, 100_000, 200_000, 199);

		assertSame(null, LmdbNativeAdaptiveArbitration.coldStartRescue(List.of(measuredIncumbent, fastRival)),
				"the guard must not fire when the incumbent carries exact-variant evidence");
	}

	/** Rival order in the offer must not change the rescue (offer-order invariance is the file's contract). */
	@Test
	void coldStartRescueIsOfferOrderInvariant() {
		LmdbNativeAdaptiveArbitration.Priced<String> unmeasured = structuralOnly("newKernel", 0);
		LmdbNativeAdaptiveArbitration.Priced<String> slowMeasured = pricedWithEvidence("slowLoop", 1,
				5_000_000, 10_000_000, 20_000_000, 32);
		LmdbNativeAdaptiveArbitration.Priced<String> fastMeasured = pricedWithEvidence("fastLoop", 2,
				50_000, 100_000, 200_000, 32);

		LmdbNativeAdaptiveArbitration.Priced<String> firstOrder = LmdbNativeAdaptiveArbitration
				.coldStartRescue(List.of(unmeasured, slowMeasured, fastMeasured));
		LmdbNativeAdaptiveArbitration.Priced<String> secondOrder = LmdbNativeAdaptiveArbitration
				.coldStartRescue(List.of(unmeasured, fastMeasured, slowMeasured));

		assertSame(firstOrder, secondOrder, "rescue must not depend on rival offer order");
	}

	/** A rival below the evidence floor is not a trustworthy rescue target. */
	@Test
	void rivalsBelowTheEvidenceFloorDoNotRescue() {
		LmdbNativeAdaptiveArbitration.Priced<String> unmeasured = structuralOnly("newKernel", 0);
		LmdbNativeAdaptiveArbitration.Priced<String> barelyMeasured = pricedWithEvidence("loop", 1,
				50_000, 100_000, 200_000, 2);

		assertSame(null, LmdbNativeAdaptiveArbitration.coldStartRescue(List.of(unmeasured, barelyMeasured)),
				"two samples are not enough evidence to overrule the ladder");
	}

	/**
	 * The completed-sample exploration quota is gone: uncertain rivals are examined through {@code maybeProbe}, which
	 * refuses without an abort-safe harness, refuses without ledger credit, and — once financed — returns exactly one
	 * bounded probe carrying a live reservation. The starvation problem the old quota addressed (LIBRARY q10) is now
	 * answered by a deadline-bounded trial instead of up to three unbounded executions.
	 */
	@Test
	void probesRequireAHarnessCreditAndReturnAtMostOneBoundedTrial() {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		LmdbNativeAdaptiveArbitration.Priced<String> incumbent = pricedWithEvidence("kernel", 0,
				5_000_000, 10_000_000, 20_000_000, 12);
		LmdbNativeAdaptiveArbitration.Priced<String> starved = structuralOnly("starvedGroups", 2);
		List<LmdbNativeAdaptiveArbitration.Priced<String>> priced = List.of(incumbent, starved);
		LmdbNativeProbeConfig config = LmdbNativeProbeConfig.defaults();
		LmdbNativeQueryProbeBudget budget = new LmdbNativeQueryProbeBudget();

		assertSame(null, LmdbNativeAdaptiveArbitration.maybeProbe(priced, incumbent, model,
				new LmdbNativeAdaptiveArbitration.ProbeContext(config, budget, false)),
				"a site without an abort-safe harness never probes");
		assertSame(null, LmdbNativeAdaptiveArbitration.maybeProbe(priced, incumbent, model,
				new LmdbNativeAdaptiveArbitration.ProbeContext(config, budget, true)),
				"a zero-credit ledger cannot finance a probe");

		store.safetyLedger().earn(1_000_000_000_000L);
		LmdbNativeAdaptiveArbitration.DispatchPlan.Probe<String> probe = LmdbNativeAdaptiveArbitration
				.maybeProbe(priced, incumbent, model,
						new LmdbNativeAdaptiveArbitration.ProbeContext(config, budget, true));
		assertSame(starved.candidate(), probe.trial(), "the uncertain rival is the probe target");
		assertSame(incumbent.candidate(), probe.fallback(), "the incumbent is retained as fallback");
		assertSame(true, probe.deadlineNanos() <= (long) (incumbent.prediction().expectedNanos() / config.gamma()),
				"the deadline never exceeds the decision-useful bound");
		probe.reservation().refund();

		assertSame(null, LmdbNativeAdaptiveArbitration.maybeProbe(priced, incumbent, model,
				new LmdbNativeAdaptiveArbitration.ProbeContext(config, budget, true)),
				"spacing forbids a consecutive probe even with credit remaining");
	}

	private static LmdbNativeAdaptiveArbitration.Priced<String> structuralOnly(String family, int preference) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, 100);
		LmdbNativeCostEstimate estimate = new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector,
				100, 0.1);
		return new LmdbNativeAdaptiveArbitration.Priced<>(
				new LmdbNativeAdaptiveArbitration.Candidate<>(estimate, preference, observation -> family),
				LmdbNativeCostPrediction.ordinalOnly("never lowered"));
	}

	/** Builds a numerically priced test quote in the new posterior shape from classic interval inputs. */
	private static LmdbNativeCostPrediction testPrediction(LmdbNativePhysicalVariantKey key, double low95,
			double expected, double high95, double low99, double high99, long evidence) {
		double sigma = expected > 0.0 && high95 > expected ? Math.log(high95 / expected) / 1.959963984540054 : 0.1;
		LmdbNativeCostPrediction.Components components = new LmdbNativeCostPrediction.Components(
				LmdbNativeRegimeKey.STEADY, LmdbNativeCostPosteriorStore.Lane.DIRECT,
				LmdbNativeFamilyShapeKey.of(key), 0.0, expected > 0.0 ? Math.log(expected) : 0.0, 0.0, 0.0,
				sigma * sigma, 0.0);
		return new LmdbNativeCostPrediction(low95, expected, high95, low99, high99, Math.min(low99, expected),
				Math.max(high99, expected), LmdbNativeCostPrediction.PriceBasis.DIRECT_POSTERIOR, true, false,
				evidence, LmdbNativeCostPrediction.EvidenceSource.EXACT_VARIANT, components, "test");
	}

	private static LmdbNativeAdaptiveArbitration.Priced<String> pricedWithEvidence(String family, int preference,
			double low95, double expected, double high95, long evidence) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, expected);
		LmdbNativeCostEstimate estimate = new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector,
				expected, 0.1);
		LmdbNativeCostPrediction prediction = testPrediction(key, low95, expected, high95, low95, high95, evidence);
		return new LmdbNativeAdaptiveArbitration.Priced<>(
				new LmdbNativeAdaptiveArbitration.Candidate<>(estimate, preference, observation -> family),
				prediction);
	}

	private static LmdbNativeAdaptiveArbitration.Priced<String> pricedWithProperties(String family, int preference,
			double low95, double expected, double high95, double low99, double high99, boolean propertyPreserving) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family + (propertyPreserving ? "-ordered" : "-hashed"))
				.propertyPreserving(propertyPreserving)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, expected);
		LmdbNativeCostEstimate estimate = new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector,
				expected, 0.1);
		LmdbNativeCostPrediction prediction = testPrediction(key, low95, expected, high95, low99, high99, 64);
		return new LmdbNativeAdaptiveArbitration.Priced<>(
				new LmdbNativeAdaptiveArbitration.Candidate<>(estimate, preference, observation -> family),
				prediction);
	}

	private static LmdbNativeAdaptiveArbitration.Priced<String> priced(String family, int preference, double low95,
			double expected, double high95) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, expected);
		LmdbNativeCostEstimate estimate = new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector,
				expected, 0.1);
		LmdbNativeCostPrediction prediction = testPrediction(key, low95, expected, high95,
				Math.max(0D, low95 - 5D), high95 + 5D, 64);
		return new LmdbNativeAdaptiveArbitration.Priced<>(
				new LmdbNativeAdaptiveArbitration.Candidate<>(estimate, preference, observation -> family),
				prediction);
	}
}
